# %% ../nbs/11_agent_workbench.ipynb #dd85b0c4
def _render_context_lines(context):
    "Render notebook evidence, reuse advice, and symbol context lines."
    lines = ["", "Relevant notebooks:"]
    lines.extend(
        f"- {item['path']} score={item['score']}"
        for item in context.get("selected_notebooks", [])
    )
    lines.extend(["", "Evidence cells:"])
    for item in context.get("evidence", []):
        lines.append(f"- {item['path']} id={item['id']}")
        if item.get("context"): lines.append(item["context"])
    if context.get("problem_memory"):
        lines.extend(["", "Problem memory:", context["problem_memory"]])
    reuse = context.get("reuse_advice") or {}
    if reuse.get("matches") or reuse.get("notebooks"):
        lines.extend(["", "Search-before-write:"])
        for item in reuse.get("matches", [])[:3]:
            lines.append(f"- reuse {item['symbol']} in {item['path']} id={item['cell_id']} score={item['score']}")
        for item in reuse.get("notebooks", [])[:3]:
            lines.append(f"- inspect {item['path']} score={item['score']}")
    placement = context.get("placement_advice") or {}
    if placement.get("candidates"):
        lines.extend(["", "Placement candidates:"])
        for item in placement.get("candidates", [])[:3]:
            lines.append(f"- {item['path']} score={item['score']} reasons={'; '.join(item.get('reasons', []))}")
    if context.get("symbol_summary"):
        lines.extend(["", "Symbol consequences:", context["symbol_summary"]])
    return lines

# %% ../nbs/11_agent_workbench.ipynb #0a8507b3
def _render_notebook_craft_lines():
    "Render notebook craft guidance for the workbench executor."
    body = """
Notebook craft:
- Small notebook loop: inspect existing cells, run or sketch a tiny proof, write the smallest exported code, add trailing Markdown rationale, add a visible example, add a focused hidden test, execute the narrowest check.
- Prefer replace_lines or one small insert_cells call when the existing shape is sound.
- If the existing cell is confusing, brittle, duplicated, or fighting the problem, delete or rewrite the scoped code instead of layering patches on top.
- Keep notebooks coherent: small markdown and code cells, one idea at a time.
- Keep each story in source order: exported code, trailing description, visible examples, and small tests near the behavior they protect.
- Explain rationale: why the shape solves the problem, what tradeoffs it rejects, and why nearby alternatives do not fit.
- End with diff_nb plus style_check(changed_only=True) or doctor(scopes='error,warning,style'), and resolve new notebook smells before stopping.
"""
    return ["", *body.strip().splitlines()]

# %% ../nbs/11_agent_workbench.ipynb #d359c484
def _render_empirical_lines(contract):
    "Render empirical-loop guidance for the workbench executor."
    settings = _empirical_settings(contract)
    mode = "hard" if settings.get("enforce") else "soft"
    if not settings.get("enabled"):
        return ["", "Empirical loop:", "- Disabled by contract."]
    return [
        "",
        f"Empirical loop ({mode} gate):",
        "- Try the behavior first with run_code before changing notebook source.",
        "- Inspect live state with inspect_state before writing the final shape.",
        "- Implement the smallest useful cell change, then add example and test cells.",
        "- Execute the focused final example or test with execute_cell after writing.",
    ]

# %% ../nbs/11_agent_workbench.ipynb #323a0f78
def _render_workbench_plan(contract, taste, context):
    "Render the executor-facing plan with taste, budgets, context, and stop rules."
    lines = [
        *_render_workbench_header(contract, taste),
        *_render_context_lines(context),
        *_render_notebook_craft_lines(),
        *_render_empirical_lines(contract),
        "",
        "Stop rules:",
        "- Prefer the smallest clear diff; sometimes that is deleting bad code and rewriting the scoped behavior.",
        "- Modify existing code before adding helpers, but do not preserve a bad shape just because it exists.",
        "- Do not add compatibility scaffolding unless the contract says so.",
        "- Stop once the contract is satisfied and verification is green.",
        "",
        "Verification:",
        _render_list(contract.get("verification", [])),
    ]
    return "\n".join(lines).rstrip()

# %% ../nbs/11_agent_workbench.ipynb #7131526e
def agent_workbench_result(
    goal: str,  # Desired software-development outcome
    notebook: str | None = None,  # Optional notebook/path to narrow context and execute against
    contract_file: str | None = None,  # Optional JSON contract overrides
    execute: bool = False,  # Execute the rendered plan through execute_plan
    max_steps: int = 8,  # Maximum inner-agent steps when executing
    timeout: int = 30,  # Per-cell timeout for execute_plan
    session_id: str | None = None,  # Reuse an in-memory edit session when provided
    reset_session: bool = False,  # Drop an existing in-memory edit session first
    feedback_rounds: int = 3,  # Maximum mutation feedback rounds
    enforce_empirical: bool = False,  # Promote empirical-loop warnings to hard failures
) -> dict:
    "Build the structured workbench result without CLI printing side effects."
    overrides = _load_contract_file(contract_file)
    contract_goal = overrides.pop("goal", goal)
    contract = make_task_contract(contract_goal, **overrides)
    if enforce_empirical:
        contract = _deep_merge(contract, {"empirical": {"enforce": True}})
    context_path = notebook or "nbs"
    taste = _deep_merge(
        load_taste_profile(project_path=context_path), contract.get("taste", {})
    )
    context = compile_context(
        contract["goal"], path=context_path, contract=contract, taste=taste
    )
    baseline = capture_state(context_path)
    budgets = contract.get("budgets", {})
    max_plan_chars = min(
        int(
            budgets.get(
                "max_rendered_plan_chars", _WORKBENCH_MAX_RENDERED_PLAN_CHARS
            )
        ),
        _WORKBENCH_MAX_RENDERED_PLAN_CHARS,
    )
    rendered_plan = cap_text(_render_workbench_plan(contract, taste, context), max_plan_chars)
    empirical_hard = _empirical_settings(contract).get("enforce")
    result = dict(
        summary="agent_workbench prepared execution context",
        contract=contract,
        taste=taste,
        context=context,
        baseline=baseline,
        rendered_plan=rendered_plan,
        expected_gates=dict(
            hard=[
                "max_files",
                "max_cells",
                "max_added_lines",
                "public_api",
                "generated/source sync",
                "new doctor errors",
            ] + (["empirical_loop"] if empirical_hard else []),
            soft=["style_delta", "readability_delta", "test_clarity", "notebook_story"]
            + ([] if empirical_hard else ["empirical_loop"]),
        ),
    )
    if execute:
        if not notebook:
            raise ValueError("agent_workbench execute=True requires notebook")
        max_agent_steps = int(
            budgets.get("max_agent_steps", DEFAULT_BUDGETS["max_agent_steps"])
        )
        max_steps = max(1, min(int(max_steps), max_agent_steps))
        feedback_rounds = min(
            int(feedback_rounds), max(1, max_agent_steps // max_steps)
        )
        timeout = min(
            int(timeout),
            int(budgets.get("max_run_secs", DEFAULT_BUDGETS["max_run_secs"])),
        )
        max_context_commands = int(
            budgets.get(
                "max_context_commands", DEFAULT_BUDGETS["max_context_commands"]
            )
        )
        context_steps = int(
            budgets.get("context_steps", DEFAULT_BUDGETS["context_steps"])
        )
        injected_context = json.dumps(
            {
                "goal": contract["goal"],
                "evidence": context.get("evidence", []),
                "problem_memory": context.get("problem_memory", ""),
                "reuse_advice": context.get("reuse_advice", {}),
            },
            default=str,
        )
        execution = execute_plan(
            notebook=notebook,
            plan=rendered_plan,
            injected_context=injected_context,
            max_steps=max_steps,
            timeout=timeout,
            max_context_commands=max_context_commands,
            context_steps=context_steps,
            session_id=session_id,
            reset_session=reset_session,
            feedback_rounds=feedback_rounds,
        )
        result["execution"] = execution
        result["score"] = score_patch(
            baseline, contract, path=context_path, execution=execution
        )
        result["summary"] = "agent_workbench executed plan"
    return result

# %% ../nbs/11_agent_workbench.ipynb #2927f514
def agent_workbench(
    goal: str,  # Desired software-development outcome
    notebook: str | None = None,  # Required when execute=True; also narrows context when provided
    contract_file: str | None = None,  # Optional JSON contract overrides
    execute: bool = False,  # Execute the rendered plan through execute_plan
    max_steps: int = 8,  # Maximum inner-agent steps when executing
    timeout: int = 30,  # Per-cell timeout for execute_plan
    session_id: str | None = None,  # Reuse an in-memory edit session when provided
    reset_session: bool = False,  # Drop an existing in-memory edit session first
    feedback_rounds: int = 3,  # Maximum mutation feedback rounds
    enforce_empirical: bool = False,  # Promote empirical-loop warnings to hard failures
) -> dict:
    "Prepare or execute a taste-aware, small-diff agent workbench run."
    return agent_workbench_result(
        goal, notebook=notebook, contract_file=contract_file, execute=execute,
        max_steps=max_steps, timeout=timeout, session_id=session_id,
        reset_session=reset_session, feedback_rounds=feedback_rounds,
        enforce_empirical=enforce_empirical,
    )
